import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast'
import { CopyImageOutcome, copyElementImageToClipboard } from 'lib/utils/copyImageToClipboard'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface copyImageLogicValues {
    isCopying: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface copyImageLogicActions {
    copyImage: (selector: string) => {
        selector: string
    }
    setIsCopying: (isCopying: boolean) => {
        isCopying: boolean
    }
}

export type copyImageLogicType = MakeLogicType<copyImageLogicValues, copyImageLogicActions>

export const copyImageLogic = kea<copyImageLogicType>([
    path(['lib', 'components', 'Scenes', 'InsightOrDashboard', 'copyImageLogic']),
    actions({
        copyImage: (selector: string) => ({ selector }),
        setIsCopying: (isCopying: boolean) => ({ isCopying }),
    }),
    reducers({
        isCopying: [
            false,
            {
                setIsCopying: (_, { isCopying }) => isCopying,
            },
        ],
    }),
    listeners(({ actions }) => ({
        copyImage: async ({ selector }) => {
            const element = document.querySelector<HTMLElement>(selector)
            if (!element) {
                lemonToast.error('Could not find anything to copy. Reload the page and try again.')
                return
            }

            actions.setIsCopying(true)
            let outcome: CopyImageOutcome
            try {
                outcome = await copyElementImageToClipboard(element)
            } finally {
                actions.setIsCopying(false)
            }

            if (outcome === 'copied') {
                lemonToast.success('Image copied to clipboard')
            } else if (outcome === 'unsupported') {
                lemonToast.error('This browser cannot copy images. Use Export to download a PNG instead.')
            } else {
                lemonToast.error('Could not copy the image. Use Export to download a PNG instead.')
            }

            // Browsers vary in how well they render and accept an image built from the live DOM, so the
            // outcome is worth measuring rather than assuming.
            posthog.capture('copied element image', { outcome, selector })
        },
    })),
])
